import { registerHooks } from 'node:module';
import { existsSync } from 'node:fs';
import { fileURLToPath, pathToFileURL } from 'node:url';
registerHooks({ resolve(specifier, context, next) {
  if (specifier === 'vitest') return { url: new URL('./vitestBridge.mjs', import.meta.url).href, shortCircuit: true };
  if (specifier === 'decimal.js') return { url: new URL('./decimal.mjs', import.meta.url).href, shortCircuit: true };
  if (specifier === 'zustand') return { url: new URL('./zustandBridge.mjs', import.meta.url).href, shortCircuit: true };
  if (specifier === 'zustand/middleware') return { url: new URL('./persist.ts', import.meta.url).href, shortCircuit: true };
  if (specifier.startsWith('.') && context.parentURL?.startsWith('file:')) {
    const base = fileURLToPath(new URL(specifier, context.parentURL));
    for (const suffix of ['.ts', '/index.ts'])
      if (existsSync(base + suffix)) return { url: pathToFileURL(base + suffix).href, shortCircuit: true };
  }
  return next(specifier, context);
}});

