import assert from 'node:assert/strict';
export const cases=[], hooks=[];
export const it=(name,fn)=>cases.push({name,fn});
it.each=(items)=>(name,fn)=>items.forEach(item=>it(name.replace('%s',String(item)),()=>fn(...(Array.isArray(item)?item:[item]))));
export const afterEach=fn=>hooks.push(fn);
export const vi={fn:(implementation=()=>{})=>{const fn=(...args)=>{fn.mock.calls.push(args);return implementation(...args);};fn.mock={calls:[]};return fn;}};
let assertions=0;
const matches=(value,pattern)=>pattern!==null&&typeof pattern==='object'?Object.entries(pattern).every(([k,v])=>matches(value?.[k],v)):Object.is(value,pattern);
export const expect=(value)=>{
  const make=negated=>{
    const check=predicate=>{assertions++;assert.equal(!!predicate,!negated);};
    return {
      get not(){return make(!negated);},
      toBe:expected=>check(Object.is(value,expected)),
      toEqual:expected=>{if(!negated){assert.deepEqual(value,expected);assertions++;}else assert.notDeepEqual(value,expected);},
      toMatchObject:expected=>check(matches(value,expected)),
      toBeDefined:()=>check(value!==undefined),toBeUndefined:()=>check(value===undefined),toBeNull:()=>check(value===null),
      toHaveLength:expected=>check(value?.length===expected),
      toHaveProperty:key=>check(Object.hasOwn(value,key)),
      toHaveBeenCalled:()=>check(value.mock.calls.length>0),
      toHaveBeenCalledTimes:expected=>check(value.mock.calls.length===expected),
    };
  };return make(false);
};
export const count=()=>assertions;

