import assert from 'node:assert/strict';
import { Worker } from 'node:worker_threads';
import { once } from 'node:events';
import { CalculationExecutor } from '../m8e-calc/src/features/scientific/calculationExecutor.ts';
import { createEnvironment } from '../m8e-calc/src/engine/index.ts';
const request={version:1,id:1,kind:'execute',inputRevision:1,executionRevision:1,environmentRevision:1,
 expression:'sum(integral(sin(x),x,0,pi),k,1,100)',environment:createEnvironment(),options:{angleMode:'rad',complex:'off'},editingName:null};
function transport(){
 const native=new Worker(new URL('./thread-entry.mjs',import.meta.url));
 const listeners=new Map(),messages=[];
 let onStart;const started=new Promise(resolve=>onStart=resolve);
 native.on('message',data=>{messages.push(data);if(data.status==='started')onStart();for(const fn of listeners.get('message')??[])fn(new MessageEvent('message',{data}));});
 return {native,messages,started,listeners,postMessage:r=>native.postMessage(r),terminate:()=>native.terminate(),
 addEventListener:(type,fn)=>{const set=listeners.get(type)??new Set();set.add(fn);listeners.set(type,set);},removeEventListener:(type,fn)=>listeners.get(type)?.delete(fn)};
}
const t=transport();let complete=0;
const adapter=new CalculationExecutor(()=>{},()=>t);
adapter.submit(request,()=>complete++,()=>{throw new Error('worker failed');});
await t.started;let marker=false;await new Promise(resolve=>setImmediate(()=>{marker=true;resolve();}));
assert.ok(marker);assert.equal(complete,0);
const exited=once(t.native,'exit');adapter.cancel();await exited;
assert.equal(complete,0);assert.ok([...t.listeners.values()].every(list=>list.size===0));assert.equal(t.messages.filter(m=>m.status==='success').length,0);adapter.dispose();
const second=transport();const finished=new Promise(resolve=>second.native.on('message',data=>{if(data.status==='success')resolve(data);}));second.postMessage(request);
const result=await finished;assert.equal(result.calculation.value.value,'200.00000000000000000000000007193949273708873248005');await second.native.terminate();
console.log(JSON.stringify({realWorkerCases:2,mainMarkerBeforeResult:marker,cancelledBeforeFinalResponse:true,postCancelCommits:complete,remainingAdapterListeners:0,value:result.calculation.value,note:'Actual calculation.worker.ts in Node worker_threads via explicit browser-transport bridge; no production browser acceptance.'}));
